 id,slug,title,seoTitle,description,metaDescription:description,opening:answer.replace(/<[^>]*>/g,''),tag:'Break-Even Concepts',tags:[cluster,'Worked examples','Planning assumptions'],cluster,calculatorSlug,published:financeGuideDate,modified:financeGuideDate,editorialStatus:'published',image:`/images/blog/finance-complete-${slug}.svg`,alt,imageCaption:'Original MyBreakeven illustration. Numerical examples are fictional teaching cases, not observed results or offers.',features:['Original reconciled examples','Explicit assumptions and limitations','Primary references and connected tools'],answerHtml:`<p id="quick-answer">${answer}</p>`,html:sections.map(([id,title,html])=>section(id,title,html)).join(''),sectionLinks:[['quick-answer','Direct answer'],...sections.map(([id,title])=>[id,title]),['guide-faqs','Questions and answers']],faq:faq.map(([q,a])=>({q,a}))
